// LineListPairReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, its own builder, one typed reason.
func LineListPairReadStrict(wire []byte) (*LineListPair, error) {
	var b LineListPairBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := LineListPairLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type LineListPairBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *LineListPairBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(LineListPair{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	LineListPairReset((*LineListPair)(p))
	return true
}
func (b *LineListPairBuilder) GetRoot() *LineListPair {
	if b.Arena.Locked {
		return nil
	}
	return (*LineListPair)(b.Arena.At(b.root))
}
func (b *LineListPairBuilder) AsConst() *LineListPair {
	if len(b.region) == 0 {
		return nil
	}
	return (*LineListPair)(unsafe.Pointer(&b.region[0]))
}
func (b *LineListPairBuilder) Region() []byte { return b.region }
func (b *LineListPairBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), LineListPairTableType(), &b.Arena)
}
func (b *LineListPairBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), LineListPairTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *LineListPairBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), LineListPairTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *LineListPairBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

// StageStatReset restores StageStat's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func StageStatReset(value *StageStat) {
	value.MedianS = 0.0
	value.P90S = 0.0
	value.N = 0
}

func StageStatMeasureBody(value *StageStat, ids *TableIds) int64 {
	bytes := int64(1)
	if value.MedianS != 0.0 {
		bytes += tableLebBytes(ids.refAtHit(166, 0x629d70c6ad2d4471)) + 1 + 8
	} // median_s
	if value.P90S != 0.0 {
		bytes += tableLebBytes(ids.refAtHit(42, 0x1c2229ffeae48168)) + 1 + 8
	} // p90_s
	if value.N != 0 {
		bytes += tableLebBytes(ids.refAtHit(294, 0xaf63e34c8601f871)) + 1 + 8
	} // n
	if ids.Overflow {
		return -1
	}
	return bytes
}

func StageStatMeasure(value *StageStat) int64 {
	var ids TableIds
	body := StageStatMeasureBody(value, &ids)
	if body < 0 || ids.Overflow {
		return -1
	}
	return 1 + body + int64(ids.Count)*8 + 8
}

func StageStatMeasureReason(value *StageStat) (int64, error) {
	size := StageStatMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
