func CostReconcileRecordLoadBuilder(b *CostReconcileRecordBuilder, wire []byte, report *TableReport) bool {
	return tableBuilderLoad(unsafe.Pointer(b.GetRoot()), b.root, &b.Main, wire, CostReconcileRecordTableType(), CostReconcileRecordTableType().NodeType, 2, report)
}

// CostReconcileRecordReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, its own builder, one typed reason.
func CostReconcileRecordReadStrict(wire []byte) (*CostReconcileRecord, error) {
	var b CostReconcileRecordBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := CostReconcileRecordLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type CostReconcileRecordBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *CostReconcileRecordBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(CostReconcileRecord{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	CostReconcileRecordReset((*CostReconcileRecord)(p))
	return true
}
func (b *CostReconcileRecordBuilder) GetRoot() *CostReconcileRecord {
	if b.Arena.Locked {
		return nil
	}
	return (*CostReconcileRecord)(b.Arena.At(b.root))
}
func (b *CostReconcileRecordBuilder) AsConst() *CostReconcileRecord {
	if len(b.region) == 0 {
		return nil
	}
	return (*CostReconcileRecord)(unsafe.Pointer(&b.region[0]))
}
func (b *CostReconcileRecordBuilder) Region() []byte { return b.region }
func (b *CostReconcileRecordBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), CostReconcileRecordTableType(), &b.Arena)
}
func (b *CostReconcileRecordBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), CostReconcileRecordTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *CostReconcileRecordBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), CostReconcileRecordTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *CostReconcileRecordBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}
