func CostCheckReset(value *CostCheck) {
	value.StreamsUsd = 0
	value.CardsUsd = 0
	value.GapUsd = 0
	value.Ok = false
	value.Orphans = TableList[CardIDRow]{}
	value.Unlisted = 0
}

