// ReadCardCountsReset restores ReadCardCounts's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func ReadCardCountsReset(value *ReadCardCounts) {
	value.Ready = 0
	value.Working = 0
	value.Done = 0
}

func ReadCardCountsMeasureBody(value *ReadCardCounts, ids *TableIds) int64 {
	bytes := int64(1)
	if value.Ready != 0 {
		bytes += tableLebBytes(ids.refAtHit(232, 0x8935baf305f374b4)) + 1 + 8
	} // ready
	if value.Working != 0 {
		bytes += tableLebBytes(ids.refAtHit(11, 0x08879e024cb91288)) + 1 + 8
	} // working
	if value.Done != 0 {
		bytes += tableLebBytes(ids.refAtHit(371, 0xdc51fb6761fd6e91)) + 1 + 8
	} // done
	if ids.Overflow {
		return -1
	}
	return bytes
}

func ReadCardCountsMeasure(value *ReadCardCounts) int64 {
	var ids TableIds
	body := ReadCardCountsMeasureBody(value, &ids)
	if body < 0 || ids.Overflow {
		return -1
	}
	return 1 + body + int64(ids.Count)*8 + 8
}

