func ReadCardCountsReadStrict(wire []byte) (*ReadCardCounts, error) {
	value := new(ReadCardCounts)
	var report TableReport
	ok := ReadCardCountsLoad(value, wire, &report)
	if err := report.Err(); err != nil || !ok {
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	return value, nil
}

