// StreamTransitionReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, its own builder, one typed reason.
func StreamTransitionReadStrict(wire []byte) (*StreamTransition, error) {
	var b StreamTransitionBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := StreamTransitionLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type StreamTransitionBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *StreamTransitionBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(StreamTransition{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	StreamTransitionReset((*StreamTransition)(p))
	return true
}
