func BeatLoadMeasure(wire []byte) int64 {
	n, _, _ := tableRegionMeasure(wire, BeatTableType(), BeatTableType().NodeType, 2)
	return n
}
func BeatLoadMeasureReason(wire []byte) (int64, error) {
	size, _, _, reason := tableRegionMeasureReason(wire, BeatTableType(), BeatTableType().NodeType, 2)
	return size, tableRefuseError(reason)
}
func BeatLoad(region, wire []byte, report *TableReport) *Beat {
	return (*Beat)(tableRegionLoad(region, wire, BeatTableType(), BeatTableType().NodeType, 2, report))
}
func BeatMeasure(value *Beat, context ...TableWriteContext) int64 {
	arena, allocator := tableWriteOptions(context)
	return tableRegionSave(unsafe.Pointer(value), BeatTableType(), nil, true, arena, allocator)
}
func BeatMeasureReason(value *Beat, context ...TableWriteContext) (int64, error) {
	arena, allocator := tableWriteOptions(context)
	size, reason := tableRegionSaveReason(unsafe.Pointer(value), BeatTableType(), nil, true, arena, allocator)
	return size, tableRefuseError(reason)
}
func BeatSave(value *Beat, buffer []byte, context ...TableWriteContext) int64 {
	arena, allocator := tableWriteOptions(context)
	return tableRegionSave(unsafe.Pointer(value), BeatTableType(), buffer, false, arena, allocator)
}
func BeatLoadBuilder(b *BeatBuilder, wire []byte, report *TableReport) bool {
	return tableBuilderLoad(unsafe.Pointer(b.GetRoot()), b.root, &b.Main, wire, BeatTableType(), BeatTableType().NodeType, 2, report)
}

// BeatReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, its own builder, one typed reason.
func BeatReadStrict(wire []byte) (*Beat, error) {
	var b BeatBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := BeatLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type BeatBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *BeatBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(Beat{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	BeatReset((*Beat)(p))
	return true
}
func (b *BeatBuilder) GetRoot() *Beat {
	if b.Arena.Locked {
		return nil
	}
	return (*Beat)(b.Arena.At(b.root))
}
func (b *BeatBuilder) AsConst() *Beat {
	if len(b.region) == 0 {
		return nil
	}
	return (*Beat)(unsafe.Pointer(&b.region[0]))
}
func (b *BeatBuilder) Region() []byte { return b.region }
func (b *BeatBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), BeatTableType(), &b.Arena)
}
func (b *BeatBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), BeatTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *BeatBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), BeatTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *BeatBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}
