// CheckedCardReset restores CheckedCard's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func CheckedCardReset(value *CheckedCard) {
	value.Id = 0
	value.Stream = 0
	value.Tier = 0
	value.Priority = 0
	value.Needs = 0
	value.Brief = 0
}

func CheckedCardMeasureBody(value *CheckedCard, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !CheckedCardSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func CheckedCardSaveBody(w *TableWriter, value *CheckedCard) bool {
	if !CheckedCardSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
