func CheckedCardLoadBody(r *TableReader, value *CheckedCard) bool {
	CheckedCardReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		switch fieldID {
		case 0x08b72e07b55c3ac0: // id
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.Id, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0x4f6a36d8e8907985: // stream
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.Stream, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0x1e6f84ef2eb65989: // tier
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.Tier, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0xf5b6ea8c35ac1e89: // priority
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.Priority, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0x4dde811e86af67ba: // needs
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.Needs, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0xf90e421e2470877f: // brief
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.Brief, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0xffffffffffffffff:
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

