// CheckedCardReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, its own builder, one typed reason.
func CheckedCardReadStrict(wire []byte) (*CheckedCard, error) {
	var b CheckedCardBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := CheckedCardLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type CheckedCardBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *CheckedCardBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(CheckedCard{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	CheckedCardReset((*CheckedCard)(p))
	return true
}
func (b *CheckedCardBuilder) GetRoot() *CheckedCard {
	if b.Arena.Locked {
		return nil
	}
	return (*CheckedCard)(b.Arena.At(b.root))
}
func (b *CheckedCardBuilder) AsConst() *CheckedCard {
	if len(b.region) == 0 {
		return nil
	}
	return (*CheckedCard)(unsafe.Pointer(&b.region[0]))
}
func (b *CheckedCardBuilder) Region() []byte { return b.region }
func (b *CheckedCardBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), CheckedCardTableType(), &b.Arena)
}
func (b *CheckedCardBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), CheckedCardTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *CheckedCardBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), CheckedCardTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *CheckedCardBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

