// ResetStreamReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, its own builder, one typed reason.
func ResetStreamReadStrict(wire []byte) (*ResetStream, error) {
	var b ResetStreamBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := ResetStreamLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type ResetStreamBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *ResetStreamBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(ResetStream{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	ResetStreamReset((*ResetStream)(p))
	return true
}
func (b *ResetStreamBuilder) GetRoot() *ResetStream {
	if b.Arena.Locked {
		return nil
	}
	return (*ResetStream)(b.Arena.At(b.root))
}
func (b *ResetStreamBuilder) AsConst() *ResetStream {
	if len(b.region) == 0 {
		return nil
	}
	return (*ResetStream)(unsafe.Pointer(&b.region[0]))
}
