// TidyCardReset restores TidyCard's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func TidyCardReset(value *TidyCard) {
	value.Id = 0
	value.Cell = 0
	value.Why = 0
	value.Finished = 0
}

func TidyCardMeasureBody(value *TidyCard, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !TidyCardSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func TidyCardSaveBody(w *TableWriter, value *TidyCard) bool {
	if !TidyCardSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
