// RoutePricesReset restores RoutePrices's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func RoutePricesReset(value *RoutePrices) {
	value.Input = 0
	value.CacheRead = 0
	value.CacheWrite = 0
	value.Output = 0
	value.ReasoningAsOutput = false
	value.LongContext = 0
	value.InputLong = 0
	value.OutputLong = 0
	value.Request = 0
	value.Billing = 0
	value.GatewayPercent = 0
	value.Source = 0
	value.AsOf = 0
}

func RoutePricesMeasureBody(value *RoutePrices, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !RoutePricesSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

