func RouteLoadRetain(region, wire []byte, retain *TableRetain, report *TableReport) *Route {
	return (*Route)(tableRegionLoadRetain(region, wire, RouteTableType(), RouteTableType().NodeType, 2, report, retain))
}
func RouteMeasureRetain(value *Route, retain *TableRetain, allocator ...TableAllocator) int64 {
	return tableRegionSaveRetain(unsafe.Pointer(value), RouteTableType(), nil, true, retain, nil, allocator...)
}
func RouteSaveRetain(value *Route, retain *TableRetain, buffer []byte, report *TableReport, allocator ...TableAllocator) int64 {
	if report == nil {
		return -1
	}
	return tableRegionSaveRetain(unsafe.Pointer(value), RouteTableType(), buffer, false, retain, report, allocator...)
}
func RouteMeasureBodyRetain(value *Route, ids *TableRetainIds) int64 {
	w := TableRetainWriter{Measuring: true, Ids: ids}
	if !RouteSaveBodyRetain(&w, value) {
		return -1
	}
	return w.Offset
}

