func MachineLoadMeasure(wire []byte) int64 {
	n, _, _ := tableRegionMeasure(wire, MachineTableType(), MachineTableType().NodeType, 2)
	return n
}
func MachineLoadMeasureReason(wire []byte) (int64, error) {
	size, _, _, reason := tableRegionMeasureReason(wire, MachineTableType(), MachineTableType().NodeType, 2)
	return size, tableRefuseError(reason)
}
func MachineLoad(region, wire []byte, report *TableReport) *Machine {
	return (*Machine)(tableRegionLoad(region, wire, MachineTableType(), MachineTableType().NodeType, 2, report))
}
func MachineMeasure(value *Machine, context ...TableWriteContext) int64 {
	arena, allocator := tableWriteOptions(context)
	return tableRegionSave(unsafe.Pointer(value), MachineTableType(), nil, true, arena, allocator)
}
func MachineMeasureReason(value *Machine, context ...TableWriteContext) (int64, error) {
	arena, allocator := tableWriteOptions(context)
	size, reason := tableRegionSaveReason(unsafe.Pointer(value), MachineTableType(), nil, true, arena, allocator)
	return size, tableRefuseError(reason)
}
func MachineSave(value *Machine, buffer []byte, context ...TableWriteContext) int64 {
	arena, allocator := tableWriteOptions(context)
	return tableRegionSave(unsafe.Pointer(value), MachineTableType(), buffer, false, arena, allocator)
}
func MachineLoadBuilder(b *MachineBuilder, wire []byte, report *TableReport) bool {
	return tableBuilderLoad(unsafe.Pointer(b.GetRoot()), b.root, &b.Main, wire, MachineTableType(), MachineTableType().NodeType, 2, report)
}

// MachineReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, its own builder, one typed reason.
func MachineReadStrict(wire []byte) (*Machine, error) {
	var b MachineBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := MachineLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type MachineBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *MachineBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(Machine{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	MachineReset((*Machine)(p))
	return true
}
func (b *MachineBuilder) GetRoot() *Machine {
	if b.Arena.Locked {
		return nil
	}
	return (*Machine)(b.Arena.At(b.root))
}
func (b *MachineBuilder) AsConst() *Machine {
	if len(b.region) == 0 {
		return nil
	}
	return (*Machine)(unsafe.Pointer(&b.region[0]))
}
func (b *MachineBuilder) Region() []byte { return b.region }
func (b *MachineBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), MachineTableType(), &b.Arena)
}
func (b *MachineBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), MachineTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *MachineBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), MachineTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *MachineBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}
