// LaneQuietReset restores LaneQuiet's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func LaneQuietReset(value *LaneQuiet) {
	value.QuietType = 0
	value.Subject = 0
	value.Why = 0
	value.FriendName = 0
	value.Run = 0
}

func LaneQuietMeasureBody(value *LaneQuiet, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !LaneQuietSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func LaneQuietSaveBody(w *TableWriter, value *LaneQuiet) bool {
	if !LaneQuietSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
