// LaneQuietReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, its own builder, one typed reason.
func LaneQuietReadStrict(wire []byte) (*LaneQuiet, error) {
	var b LaneQuietBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := LaneQuietLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type LaneQuietBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *LaneQuietBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(LaneQuiet{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	LaneQuietReset((*LaneQuiet)(p))
	return true
}
func (b *LaneQuietBuilder) GetRoot() *LaneQuiet {
	if b.Arena.Locked {
		return nil
	}
	return (*LaneQuiet)(b.Arena.At(b.root))
}
func (b *LaneQuietBuilder) AsConst() *LaneQuiet {
	if len(b.region) == 0 {
		return nil
	}
	return (*LaneQuiet)(unsafe.Pointer(&b.region[0]))
}
func (b *LaneQuietBuilder) Region() []byte { return b.region }
func (b *LaneQuietBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), LaneQuietTableType(), &b.Arena)
}
func (b *LaneQuietBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), LaneQuietTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *LaneQuietBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), LaneQuietTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *LaneQuietBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

// SuppressedReset restores Suppressed's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func SuppressedReset(value *Suppressed) {
	value.Epoch = 0
	value.N = 0
	value.Lane = 0
	value.Readers = 0
	value.Tier = 0
}

func SuppressedMeasureBody(value *Suppressed, ids *TableIds) int64 {
	bytes := int64(1)
	if value.Epoch != 0 {
		bytes += tableLebBytes(ids.refAtHit(435, 0xfc9697d1196e6ba6)) + 1 + 8
	} // epoch
	if value.N != 0 {
		bytes += tableLebBytes(ids.refAtHit(294, 0xaf63e34c8601f871)) + 1 + 8
	} // n
	if value.Lane != 0 {
		bytes += tableLebBytes(ids.refAtHit(3, 0x0460ddad9060af0f)) + 1 + 8
	} // lane
	if value.Readers != 0 {
		bytes += tableLebBytes(ids.refAtHit(219, 0x81027a1935117cdf)) + 1 + 8
	} // readers
	if value.Tier != 0 {
		bytes += tableLebBytes(ids.refAtHit(46, 0x1e6f84ef2eb65989)) + 1 + 8
	} // tier
	if ids.Overflow {
		return -1
	}
	return bytes
}

func SuppressedMeasure(value *Suppressed) int64 {
	var ids TableIds
	body := SuppressedMeasureBody(value, &ids)
	if body < 0 || ids.Overflow {
		return -1
	}
	return 1 + body + int64(ids.Count)*8 + 8
}

func SuppressedMeasureReason(value *Suppressed) (int64, error) {
	size := SuppressedMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
