// HeartbeatReset restores Heartbeat's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func HeartbeatReset(value *Heartbeat) {
	value.At = 0
	value.Ticks = 0
	value.Error = 0
	value.Failures = 0
	value.TickOverrun = 0
	value.Due = 0
	clear(value.Revisions[:])
	value.Landed = 0
	value.All = 0
	value.Full = 0
	value.Looked = 0
	value.Fresh = TableList[LineRow]{}
	value.Quiet = TableList[LaneQuietRow]{}
	SuppressedReset(&value.Suppressed)
}

