func HeartbeatLoadRetain(region, wire []byte, retain *TableRetain, report *TableReport) *Heartbeat {
	return (*Heartbeat)(tableRegionLoadRetain(region, wire, HeartbeatTableType(), HeartbeatTableType().NodeType, 2, report, retain))
}
func HeartbeatMeasureRetain(value *Heartbeat, retain *TableRetain, allocator ...TableAllocator) int64 {
	return tableRegionSaveRetain(unsafe.Pointer(value), HeartbeatTableType(), nil, true, retain, nil, allocator...)
}
func HeartbeatSaveRetain(value *Heartbeat, retain *TableRetain, buffer []byte, report *TableReport, allocator ...TableAllocator) int64 {
	if report == nil {
		return -1
	}
	return tableRegionSaveRetain(unsafe.Pointer(value), HeartbeatTableType(), buffer, false, retain, report, allocator...)
}
func HeartbeatMeasureBodyRetain(value *Heartbeat, ids *TableRetainIds) int64 {
	w := TableRetainWriter{Measuring: true, Ids: ids}
	if !HeartbeatSaveBodyRetain(&w, value) {
		return -1
	}
	return w.Offset
}

func HeartbeatSaveBodyRetain(w *TableRetainWriter, value *Heartbeat) bool {
	if !HeartbeatSaveBodyFieldsRetain(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
