// A FILE: form byte, seven reserved zeros, the LAYOUT HASH at 8, body at 16,
// then the layout behind its u32 length, then the records to the end of it.
func LoadSampleFixedMeasure(count int64) int64 {
	return TableFixedHeaderBytes + 4 + int64(len(LoadSampleFixedLayout)) + count*LoadSampleFixedRecordBytes
}

// LoadSampleFixedSave is the fixed form's writer: it returns the bytes written, or -1 for a
// buffer too short or a value outside its declared contract (§3.1); see FixedSaveReason.
func LoadSampleFixedSave(values []LoadSample, buffer []byte) int64 {
	need := LoadSampleFixedMeasure(int64(len(values)))
	if int64(len(buffer)) < need {
		return -1
	}
	clear(buffer[:TableFixedHeaderBytes])
	buffer[0] = TableFixedForm
	tableFixedPut64(buffer[TableFixedHashAt:], LoadSampleFixedHash)
	tableFixedPut32(buffer[TableFixedHeaderBytes:], uint32(len(LoadSampleFixedLayout)))
	copy(buffer[TableFixedHeaderBytes+4:], LoadSampleFixedLayout)
	at := buffer[TableFixedHeaderBytes+4+len(LoadSampleFixedLayout):]
	for k := range values {
		tableFixedPut64(at, LoadSampleFixedHash)
		clear(at[8 : 8+LoadSampleFixedBodyBytes])
		LoadSampleFixedWriteBody(at[8:], &values[k])
		at = at[LoadSampleFixedRecordBytes:]
	}
	return need
}

func LoadSampleFixedSaveReason(values []LoadSample, buffer []byte) (int64, error) {
	if n := LoadSampleFixedSave(values, buffer); n >= 0 {
		return n, nil
	}
	if int64(len(buffer)) < LoadSampleFixedMeasure(int64(len(values))) {
		return -1, TableRefuseTruncated
	}
	return -1, TableRefuseInvalidValue
}

